def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs(current, path, depth, max_depth):
        if current == goal:
            return path + [current]
        if depth == max_depth:
            return None
        row, col = current
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_row, next_col = row + dr, col + dc
            if is_valid(next_row, next_col):
                result = dfs((next_row, next_col), path + [current], depth + 1, max_depth)
                if result:
                    return result
        return None

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []
    if start == goal:
        return [start]

    max_depth = 0
    while True:
        result = dfs(start, [], 0, max_depth)
        if result:
            return result
        max_depth += 1
        if max_depth > rows * cols:
            return []
