def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs(depth, path, visited):
        if len(path) > depth:
            return False
        r, c = path[-1]
        if (r, c) == goal:
            return True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                visited.add((nr, nc))
                path.append((nr, nc))
                if dfs(depth, path, visited):
                    return True
                path.pop()
                visited.remove((nr, nc))
        return False

    if not is_valid(*start) or not is_valid(*goal):
        return []

    if start == goal:
        return [start]

    max_depth = rows * cols
    for depth in range(1, max_depth + 1):
        visited = set([start])
        path = [start]
        if dfs(depth, path, visited):
            return path

    return []
