from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) or
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start, goal, reverse=False):
        visited = set()
        queue = deque([(start, [start])])
        visited.add(start)
        while queue:
            current, path = queue.popleft()
            if current == goal:
                return path
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.' and (r, c) not in visited:
                    visited.add((r, c))
                    queue.append(((r, c), path + [(r, c)]))
        return []

    forward = bfs(start, goal)
    if forward:
        return forward

    backward = bfs(goal, start, reverse=True)
    if backward:
        return backward[:-1] + forward[::-1]

    return []
