        if current == goal:
            return path + [current]
        if depth == 0:
            return None
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                result = dfs((nr, nc), path + [current], depth - 1)
                if result:
