from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) or
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    # Bidirectional BFS
    visited_forward = {start: [start]}
    visited_backward = {goal: [goal]}
    forward_queue = deque([start])
    backward_queue = deque([goal])

    while forward_queue and backward_queue:
        # Expand forward
        if forward_queue:
            current = forward_queue.popleft()
            for neighbor in get_neighbors(*current):
                if neighbor not in visited_forward:
                    visited_forward[neighbor] = visited_forward[current] + [neighbor]
                    forward_queue.append(neighbor)
                    if neighbor in visited_backward:
                        return visited_forward[neighbor] + visited_backward[neighbor][::-1][1:]

        # Expand backward
        if backward_queue:
            current = backward_queue.popleft()
            for neighbor in get_neighbors(*current):
                if neighbor not in visited_backward:
                    visited_backward[neighbor] = visited_backward[current] + [neighbor]
                    backward_queue.append(neighbor)
                    if neighbor in visited_forward:
                        return visited_forward[neighbor] + visited_backward[neighbor][::-1][1:]

    return []
