from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(queue, visited, path_map):
        while queue:
            r, c = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    path_map[(nr, nc)] = (r, c)
                    queue.append((nr, nc))
                    if (nr, nc) == goal:
                        return True
        return False

    start_queue = deque()
    start_queue.append(start)
    start_visited = set([start])
    start_path_map = {start: None}

    goal_queue = deque()
    goal_queue.append(goal)
    goal_visited = set([goal])
    goal_path_map = {goal: None}

    while start_queue and goal_queue:
        if bfs(start_queue, start_visited, start_path_map):
            path = []
            current = goal
            while current:
                path.append(current)
                current = start_path_map.get(current)
            return path[::-1]
        if bfs(goal_queue, goal_visited, goal_path_map):
            path = []
            current = start
            while current:
                path.append(current)
                current = goal_path_map.get(current)
            return path[::-1]

    return []
