    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(start, goal, visited, other_visited):
        queue = deque([(start, [start])])
        visited.add(start)
        while queue:
            current, path = queue.popleft()
            if current in other_visited:
                return path + other_visited[current][::-1]
            for dr, dc in directions:
                nr, nc = current[0] + dr, current[1] + dc
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), path + [(nr, nc)]))
        return []

    forward_visited = set()
    backward_visited = set()
    forward_queue = deque([start])
    backward_queue = deque([goal])
    forward_visited.add(start)
    backward_visited.add(goal)

    while forward_queue and backward_queue:
        forward_result = bfs(start, goal, forward_visited, backward_visited)
        if forward_result:
            return forward_result
        backward_result = bfs(goal, start, backward_visited, forward_visited)
        if backward_result:
            return backward_result
        if not forward_queue:
            break
        current = forward_queue.popleft()
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if is_valid(nr, nc) and (nr, nc) not in forward_visited:
                forward_visited.add((nr, nc))
                forward_queue.append((nr, nc))
        if not backward_queue:
            break
        current = backward_queue.popleft()
        for dr, dc in directions:
            nr, nc = current[0] + dr, current[1] + dc
            if is_valid(nr, nc) and (nr, nc) not in backward_visited:
                backward_visited.add((nr, nc))
                backward_queue.append((nr, nc))
    return []
