        dr, dc = direction
        jump_points = []
        while True:
            r += dr
            c += dc
            if not is_free(r, c):
                break
            jump_points.append((r, c))
        return jump_points

    def get_jump_directions(r, c):
        directions = []
        if is_free(r, c - 1):
            directions.append((-1, 0))
        if is_free(r, c + 1):
            directions.append((1, 0))
        if is_free(r - 1, c):
            directions.append((0, -1))
        if is_free(r + 1, c):
            directions.append((0, 1))
        return directions

    def jump_search(r, c, visited):
        if (r, c) == goal:
            return [(r, c)]
        queue = deque([(r, c, [ (r, c) ])])
        visited.add((r, c))
        while queue:
            curr_r, curr_c, path = queue.popleft()
            for dr, dc in get_jump_directions(curr_r, curr_c):
                jump_points = get_jump_points(curr_r, curr_c, (dr, dc))
                for jump_r, jump_c in jump_points:
                    if (jump_r, jump_c) not in visited:
                        new_path = path + [ (jump_r, jump_c) ]
                        if (jump_r, jump_c) == goal:
                            return new_path
                        visited.add((jump_r, jump_c))
                        queue.append( (jump_r, jump_c, new_path) )
        return []

    visited = set()
    result = jump_search(start[0], start[1], visited)
    return result if result else []
