import heapq

def solve(grid, start, goal):
    if not grid or start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def heuristic(pos, goal):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    def a_star(start, goal, reverse=False):
        pq = []
        heapq.heappush(pq, (heuristic(start, goal), 0, start, None))
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}

        while pq:
            _, cost, current, prev = heapq.heappop(pq)
            if current == goal:
                path = [current]
                while prev:
                    path.append(prev)
                    prev = came_from[prev]
                return path[::-1]

            if reverse:
                for dr, dc in directions:
                    neighbor = (current[0] + dr, current[1] + dc)
                    if is_valid(neighbor):
                        tentative_g = g_score[current] + 1
                        if neighbor not in g_score or tentative_g < g_score[neighbor]:
                            came_from[neighbor] = current
                            g_score[neighbor] = tentative_g
                            f_score[neighbor] = tentative_g + heuristic(neighbor, goal)
                            heapq.heappush(pq, (f_score[neighbor], tentative_g, neighbor, current))
            else:
                for dr, dc in directions:
                    neighbor = (current[0] + dr, current[1] + dc)
                    if is_valid(neighbor):
                        tentative_g = g_score[current] + 1
                        if neighbor not in g_score or tentative_g < g_score[neighbor]:
                            came_from[neighbor] = current
                            g_score[neighbor] = tentative_g
                            f_score[neighbor] = tentative_g + heuristic(neighbor, goal)
                            heapq.heappush(pq, (f_score[neighbor], tentative_g, neighbor, current))
        return []

    forward_path = a_star(start, goal)
    if forward_path:
        return forward_path

    reverse_path = a_star(goal, start, reverse=True)
    if reverse_path:
        return reverse_path

    return []
