import heapq

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []
    if start == goal:
        return [start]

    def heuristic(pos):
        return abs(pos[0] - goal_row) + abs(pos[1] - goal_col)

    def get_neighbors(pos):
        r, c = pos
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def bidirectional_a_star(start, goal):
        open_set_f = [(heuristic(start), start)]
        open_set_b = [(heuristic(goal), goal)]
        came_from_f = {}
        came_from_b = {}
        g_score_f = {start: 0}
        g_score_b = {goal: 0}
        found = False

        while open_set_f and open_set_b:
            _, current = heapq.heappop(open_set_f)
            if current == goal:
                found = True
                break
            for neighbor in get_neighbors(current):
                tentative_g = g_score_f[current] + 1
                if neighbor not in g_score_f or tentative_g < g_score_f[neighbor]:
                    g_score_f[neighbor] = tentative_g
                    heapq.heappush(open_set_f, (g_score_f[neighbor] + heuristic(neighbor), neighbor))
                    came_from_f[neighbor] = current

            _, current = heapq.heappop(open_set_b)
            if current == start:
                found = True
                break
            for neighbor in get_neighbors(current):
                tentative_g = g_score_b[current] + 1
                if neighbor not in g_score_b or tentative_g < g_score_b[neighbor]:
                    g_score_b[neighbor] = tentative_g
                    heapq.heappush(open_set_b, (g_score_b[neighbor] + heuristic(neighbor), neighbor))
                    came_from_b[neighbor] = current

        if not found:
            return []

        path = []
        if current == goal:
            path = [current]
            while current in came_from_f:
                current = came_from_f[current]
                path.append(current)
            path.reverse()
        else:
            path = [current]
            while current in came_from_b:
                current = came_from_b[current]
                path.append(current)
            path.reverse()
            while path[-1] in came_from_f:
                path.append(came_from_f[path[-1]])
        return path

    path = bidirectional_a_star(start, goal)
    if path and grid[path[0][0]][path[0][1]] == '.' and grid[path[-1][0]][path[-1][1]] == '.':
        return path
    return []
