```python
import heapq

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if (start_row < 0 or start_row >= rows or start_col < 0 or start_col >= cols or
        grid[start_row][start_col] == '#' or
        grid[goal_row][goal_col] == '#'):
        return []

    if start == goal:
        return [start]

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def heuristic(pos):
        r, c = pos
        return abs(r - goal_row) + abs(c - goal_col)

    def a_star(start, goal, reverse=False):
        if reverse:
            return lambda pos: -heuristic(pos)
        return heuristic

    def reconstruct_path(came_from, start, goal):
        path = [goal]
        while path[-1] != start:
            path.append(came_from[path[-1]])
        return path[::-1]

    def bidirectional_a_star():
        forward_open = [(heuristic(start), 0, start)]
        forward_closed = set()
        forward_came_from = {}

        backward_open = [(heuristic(goal), 0, goal)]
        backward_closed = set()
        backward_came_from = {}

        while forward_open and backward_open:
            # Forward search
            f_cost, f_dist, f_pos = heapq.heappop(forward_open)
            if f_pos in forward_closed:
                continue
            forward_closed.add(f_pos)
            for neighbor in get_neighbors(*f_pos):
                if neighbor not in forward_closed:
                    new_dist = f_dist + 1
                    heapq.heappush(forward_open, (new_dist + heuristic(neighbor), new_dist, neighbor))
                    forward_came_from[neighbor] = f_pos

            # Check for meeting point
            if f_pos in backward_closed:
                path = reconstruct_path(forward_came_from, start, f_pos)
                path += reconstruct_path(backward_came_from, goal, f_pos)[::-1]
                return path

            # Backward search
            b_cost, b_dist, b_pos = heapq.heappop(backward_open)
            if b_pos in backward_closed:
                continue
            backward_closed.add(b_pos)
            for neighbor in get_neighbors(*b_pos):
                if neighbor not in backward_closed:
                    new_dist = b_dist + 1
                    heapq.heappush(backward_open, (new_dist + heuristic(neighbor), new_dist, neighbor))
                    backward_came_from[neighbor] = b_pos

            # Check for meeting point
            if b_pos in forward_closed:
                path = reconstruct_path(backward_came_from, start, b_pos)
                path += reconstruct_path(forward_came_from, goal, b_pos)[::-1]
                return path

        return []

    return bidirectional_a_star()
