import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        prev = [-1] * n

        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                break
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    prev[v] = u
                    heapq.heappush(heap, (dist[v], v))
        if dist[end] == float('inf'):
            return -1, None
        path = []
        current = end
        while current != -1:
            path.append(current)
            current = prev[current]
        path.reverse()
        return dist[end], path

    dist_from_s, _ = dijkstra(s, t)
    if dist_from_s == -1:
        return -1

    dist_from_t, _ = dijkstra(t, s)
    if dist_from_t == -1:
        return -1

    return dist_from_s
