import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bidirectional Dijkstra
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        came_from = {}

        while heap:
            curr_dist, u = heapq.heappop(heap)
            if u == end:
                break
            if curr_dist > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > curr_dist + w:
                    dist[v] = curr_dist + w
                    heapq.heappush(heap, (dist[v], v))
                    came_from[v] = u
        return dist, came_from

    # Run Dijkstra from both ends
    dist_s, _ = dijkstra(s, t)
    dist_t, _ = dijkstra(t, s)

    # Reverse edges for reverse direction
    reverse_adj = [[] for _ in range(n)]
    for u, v, w in edges:
        reverse_adj[v].append((u, w))

    dist_t_rev, _ = dijkstra(t, s, reverse_adj)

    # Find the minimum path by combining both directions
    min_dist = float('inf')
    for node in range(n):
        if dist_s[node] != float('inf') and dist_t_rev[node] != float('inf'):
            min_dist = min(min_dist, dist_s[node] + dist_t_rev[node])

    return min_dist if min_dist != float('inf') else -1
